-- PREPARATORY SQL ONLY. Not applied to any connected project.
-- Mirrored in supabase/migrations/20261016162535_operia_profile.sql, generated by Supabase CLI.
-- Adds a profile and per-company Opéria metadata without altering Nanayé amounts/statuses.
begin;
alter table public.crm_brands add column profile text not null default 'general'
 check(profile in ('general','operia'));
alter table public.crm_records add column metadata jsonb not null default '{}'::jsonb;

create function crm_private.valid_operia_metadata(m jsonb) returns boolean
language plpgsql immutable security invoker set search_path='' as $$
declare o jsonb; f jsonb; a jsonb; k text; n numeric;
begin
 if jsonb_typeof(m) is distinct from 'object' or octet_length(m::text)>300000 then return false; end if;
 if not (m ? 'operia') then return true; end if;
 o:=m->'operia';
 if jsonb_typeof(o) is distinct from 'object' then return false; end if;
 if o ? 'schemaVersion' and o->>'schemaVersion'<>'1' then return false; end if;
 foreach k in array array['siren','creationDate','city','naf','employees','registryStatus','registryDate','registrySource','contactName','contactRole','contactSource','contactVerifiedAt','businessEvidence','businessSource','businessDate','need','stage','nextAction','due','originator'] loop
  if o ? k and jsonb_typeof(o->k) is distinct from 'string' then return false; end if;
 end loop;
 if coalesce(o->>'siren','')<>'' and o->>'siren' !~ '^[0-9]{9}$' then return false; end if;
 if coalesce(o->>'stage','À qualifier') not in ('À qualifier','Qualifié','Contacté','En échange','Démo planifiée','Démo réalisée','Proposition','Gagné','Perdu','Opposition') then return false; end if;
 if coalesce(o->>'registryStatus','') not in ('','A','C') then return false; end if;
 if o ? 'monthlyHtCents' and o->'monthlyHtCents'<>'null'::jsonb then
  if jsonb_typeof(o->'monthlyHtCents') is distinct from 'number' then return false; end if;
  n:=(o->>'monthlyHtCents')::numeric;if n<0 or n>10000000000 or n<>trunc(n) then return false; end if;
 end if;
 if o ? 'fit' then
  f:=o->'fit';if jsonb_typeof(f) is distinct from 'object' then return false; end if;
  foreach k in array array['sites','agents'] loop
   if f ? k and f->k<>'null'::jsonb then
    if jsonb_typeof(f->k) is distinct from 'number' then return false; end if;
    n:=(f->>k)::numeric;if n<0 or n>1000000 or n<>trunc(n) then return false; end if;
   end if;
  end loop;
  if f ? 'painConfirmed' and jsonb_typeof(f->'painConfirmed') is distinct from 'boolean' then return false; end if;
 end if;
 if o ? 'legacy' and jsonb_typeof(o->'legacy') is distinct from 'object' then return false; end if;
 if o ? 'activities' then
  if jsonb_typeof(o->'activities') is distinct from 'array' then return false; end if;
  for a in select value from jsonb_array_elements(o->'activities') loop
   if jsonb_typeof(a) is distinct from 'object' then return false; end if;
   foreach k in array array['id','kind','at','note','source'] loop
    if a ? k and jsonb_typeof(a->k) is distinct from 'string' then return false; end if;
   end loop;
   if a ? 'amountHtCents' and a->'amountHtCents'<>'null'::jsonb then
    if jsonb_typeof(a->'amountHtCents') is distinct from 'number' then return false; end if;
    n:=(a->>'amountHtCents')::numeric;if n<0 or n>10000000000 or n<>trunc(n) then return false; end if;
   end if;
  end loop;
 end if;
 return true;
end; $$;
revoke all on function crm_private.valid_operia_metadata(jsonb) from public,anon;
grant execute on function crm_private.valid_operia_metadata(jsonb) to authenticated;
alter table public.crm_records add constraint crm_records_metadata_valid check(crm_private.valid_operia_metadata(metadata));

-- Include archived and opposed records so importing the same company never recreates it.
create unique index crm_operia_siren_unique on public.crm_records(brand_id,(metadata->'operia'->>'siren'))
 where kind='contact' and coalesce(metadata->'operia'->>'siren','')<>'';
create unique index crm_operia_legacy_unique on public.crm_records(brand_id,(metadata->'operia'->'legacy'->>'source'),(metadata->'operia'->'legacy'->>'id'))
 where kind='contact' and coalesce(metadata->'operia'->'legacy'->>'source','')<>'' and coalesce(metadata->'operia'->'legacy'->>'id','')<>'';

create function crm_private.operia_record_before() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if new.metadata ? 'operia' then
  if new.kind<>'contact' then raise exception 'Operia company metadata requires a contact'; end if;
  if not exists(select 1 from public.crm_brands where id=new.brand_id and profile='operia') then raise exception 'Operia profile required'; end if;
  if new.metadata->'operia'->>'stage'='Opposition' then new.status:='Ne plus contacter'; end if;
  if new.status='Ne plus contacter' then new.metadata:=jsonb_set(new.metadata,'{operia,stage}','"Opposition"'::jsonb); end if;
 end if;
 -- Metadata-only changes cannot silently lift an existing opposition, including via stale imports.
 if TG_OP='UPDATE' and old.status='Ne plus contacter' and new.status<>'Ne plus contacter' and (new.metadata ? 'operia' or old.metadata ? 'operia') then
  raise exception 'Opposition cannot be removed by this import or profile update';
 end if;
 return new;
end; $$;
revoke all on function crm_private.operia_record_before() from public,anon,authenticated;
create trigger crm_operia_record_before before insert or update on public.crm_records for each row execute function crm_private.operia_record_before();

-- Keep privileged writes private. No new table UPDATE grants or RLS policies are introduced.
create function crm_private.crm_create_profiled_brand(brand_name text,brand_profile text) returns uuid
language plpgsql security definer set search_path='' as $$
declare b uuid; n text;
begin
 if auth.uid() is null or not exists(select 1 from public.crm_members where user_id=auth.uid() and role='owner') then raise exception 'Owner required'; end if;
 if brand_profile not in ('general','operia') or brand_profile is null then raise exception 'Invalid profile'; end if;
 select display_name into n from public.crm_members where user_id=auth.uid() and role='owner' order by id limit 1;
 insert into public.crm_brands(name,profile) values(trim(brand_name),brand_profile) returning id into b;
 insert into public.crm_members(brand_id,user_id,display_name,role) values(b,auth.uid(),n,'owner');return b;
end; $$;
revoke all on function crm_private.crm_create_profiled_brand(text,text) from public,anon;
grant execute on function crm_private.crm_create_profiled_brand(text,text) to authenticated;
create function public.crm_create_profiled_brand(brand_name text,brand_profile text) returns uuid language sql security invoker set search_path='' as $$
 select crm_private.crm_create_profiled_brand(brand_name,brand_profile);
$$;
revoke all on function public.crm_create_profiled_brand(text,text) from public,anon;
grant execute on function public.crm_create_profiled_brand(text,text) to authenticated;

create function crm_private.crm_set_brand_profile(brand_id uuid,brand_profile text) returns void
language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not exists(select 1 from public.crm_members m where m.brand_id=crm_set_brand_profile.brand_id and m.user_id=auth.uid() and m.role='owner') then raise exception 'Brand owner required'; end if;
 if brand_profile not in ('general','operia') or brand_profile is null then raise exception 'Invalid profile'; end if;
 if brand_profile='general' and exists(select 1 from public.crm_records r where r.brand_id=crm_set_brand_profile.brand_id and r.metadata ? 'operia') then raise exception 'Operia companies already exist'; end if;
 update public.crm_brands b set profile=brand_profile where b.id=crm_set_brand_profile.brand_id;
end; $$;
revoke all on function crm_private.crm_set_brand_profile(uuid,text) from public,anon;
grant execute on function crm_private.crm_set_brand_profile(uuid,text) to authenticated;
create function public.crm_set_brand_profile(brand_id uuid,brand_profile text) returns void language sql security invoker set search_path='' as $$
 select crm_private.crm_set_brand_profile(brand_id,brand_profile);
$$;
revoke all on function public.crm_set_brand_profile(uuid,text) from public,anon;
grant execute on function public.crm_set_brand_profile(uuid,text) to authenticated;
commit;
